import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C1oW5ckO.js";var c=JSON.parse(`{"title":"UPnPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/upnpumpkin/docs/index.md"},"headers":[],"relativePath":"packages/upnpumpkin/docs/index.md","filePath":"packages/upnpumpkin/docs/index.md","lastUpdated":1792252144000}`),l={name:`packages/upnpumpkin/docs/index.md`},u={id:`upnpumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/upnpumpkin-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/upnpumpkin/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`UPnPumpkin `),n(`a`,{class:`header-anchor`,href:`#upnpumpkin`,"aria-label":`Permalink to “UPnPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[2]||=r(`<p>If players outside your local network need to reach your server, UPnPumpkin can ask your router to forward the Java TCP and Bedrock UDP ports using UPnP or NAT-PMP. When the network supports automatic mapping, you don&#39;t have to add those router rules by hand.</p><p>Install <code>upnpumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> folder, then restart the server. The <a href="./../README#configuration">configuration reference</a> lists the default ports and other settings. The router keeps each mapping for a limited lease; UPnPumpkin renews it halfway through that time and closes it when the server stops.</p><h2 id="check-the-mapping" tabindex="-1">Check the mapping <a class="header-anchor" href="#check-the-mapping" aria-label="Permalink to “Check the mapping”">​</a></h2><p>Run <code>/upnp status</code> to check which router UPnPumpkin found, the public address, and the state of each port. After editing <code>plugins/data/UPnPumpkin/config.toml</code>, run <code>/upnp reload</code> to apply the settings and update the mappings. If the server machine already has a public address, it doesn&#39;t need a router mapping.</p><p>Other plugins can request their own port mappings. The <code>plugins.allow_requests</code> setting turns these requests on or off, and <code>plugins.max_requests_per_plugin</code> sets how many mappings each plugin may keep open; see the <a href="./../README#configuration">configuration reference</a>. A plugin should stop refreshing its request when it no longer needs the port. UPnPumpkin closes mappings that have not been refreshed for five minutes.</p><h2 id="network-requirements" tabindex="-1">Network requirements <a class="header-anchor" href="#network-requirements" aria-label="Permalink to “Network requirements”">​</a></h2><p>Your router needs to support and have UPnP or NAT-PMP enabled, and your server needs a route to the internet through that router. A mapping cannot get around carrier-grade NAT. A second router or a container network that blocks multicast can also prevent router discovery. If multicast is blocked, set the router search address in the configuration. UPnPumpkin checks its unsupported-router list before opening ports and refuses routers on that list.</p><p>UPnP is available to devices on your local network, so run it only on a network you trust. If a port doesn&#39;t open or players still can&#39;t connect, see the <a href="./troubleshooting">troubleshooting guide</a>.</p>`,8)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};